import{_ as a,o as r,c as l,a2 as s}from"./chunks/framework.BXzK3EA4.js";const d=JSON.parse('{"title":"裸机云 Rescue（救援系统）使用指南","description":"","frontmatter":{"title":"裸机云 Rescue（救援系统）使用指南"},"headers":[],"relativePath":"ops-knowledge-base/baremetal/rescue-mode-guide.md","filePath":"ops-knowledge-base/baremetal/rescue-mode-guide.md","lastUpdated":1788259091000}'),i={name:"ops-knowledge-base/baremetal/rescue-mode-guide.md"};function o(u,e,t,c,n,p){return r(),l("div",null,[...e[0]||(e[0]=[s('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍如何通过裸机云控制台进入 Rescue（救援系统），以及 Rescue 模式的适用场景、操作步骤、登录方式及注意事项，帮助您在系统异常时进行系统维护、故障排查及数据恢复。</p><p><strong>适用产品：</strong> 裸机云（Bare Metal Cloud）</p><hr><h2 id="一、什么是-rescue-救援系统" tabindex="-1">一、什么是 Rescue（救援系统）？ <a class="header-anchor" href="#一、什么是-rescue-救援系统" aria-label="Permalink to &quot;一、什么是 Rescue（救援系统）？&quot;">​</a></h2><p>Rescue（救援系统）是一套独立于服务器原操作系统之外的临时维护环境。</p><p>当服务器无法正常启动、无法通过 SSH 或远程桌面（RDP）登录，或需要进行系统修复、数据恢复等维护操作时，可通过 Rescue 模式启动服务器进行管理。</p><blockquote><p><strong>说明：</strong></p><p>Rescue 模式不会重装操作系统，也不会格式化服务器磁盘，仅提供一个临时维护环境用于故障排查及数据维护。</p></blockquote><hr><h2 id="二、适用场景" tabindex="-1">二、适用场景 <a class="header-anchor" href="#二、适用场景" aria-label="Permalink to &quot;二、适用场景&quot;">​</a></h2><p>建议在以下场景使用 Rescue 模式：</p><ul><li>操作系统无法正常启动；</li><li>Linux 无法通过 SSH 登录；</li><li>Windows 无法通过远程桌面（RDP）登录；</li><li>系统配置错误导致无法进入系统；</li><li>需要修复系统配置或系统文件；</li><li>需要备份或恢复重要数据；</li><li>需要检查磁盘或进行其他系统维护。</li></ul><hr><h2 id="三、进入-rescue-模式" tabindex="-1">三、进入 Rescue 模式 <a class="header-anchor" href="#三、进入-rescue-模式" aria-label="Permalink to &quot;三、进入 Rescue 模式&quot;">​</a></h2><ol><li>登录 <strong>Raksmart 客户后台</strong>。</li><li>进入 <strong>产品管理</strong> → <strong>裸机云</strong>。</li><li>选择需要管理的服务器。</li><li>点击进入 <strong>管理</strong> 页面。</li><li>点击 救援系统。</li></ol><p>系统将弹出 Rescue 配置窗口。</p><hr><h2 id="四、配置-rescue-参数" tabindex="-1">四、配置 Rescue 参数 <a class="header-anchor" href="#四、配置-rescue-参数" aria-label="Permalink to &quot;四、配置 Rescue 参数&quot;">​</a></h2><h2 id="_1、选择-rescue-系统类型" tabindex="-1">1、选择 Rescue 系统类型 <a class="header-anchor" href="#_1、选择-rescue-系统类型" aria-label="Permalink to &quot;1、选择 Rescue 系统类型&quot;">​</a></h2><p>根据维护需求选择对应的 Rescue 系统。</p><p>目前支持以下类型：</p><ul><li>Windows（中文）</li><li>Windows（English）</li><li>Linux</li></ul><p>请选择适合当前维护需求的 Rescue 系统。</p><hr><h2 id="_2、设置临时密码" tabindex="-1">2、设置临时密码 <a class="header-anchor" href="#_2、设置临时密码" aria-label="Permalink to &quot;2、设置临时密码&quot;">​</a></h2><p>进入 Rescue 前，需要设置临时登录密码。</p><p>支持以下方式：</p><ul><li>系统随机生成密码；</li><li>自定义设置密码。</li></ul><blockquote><p><strong>注意：</strong></p><p><strong>请妥善保存当前密码，该密码仅显示一次，后续无法再次查看。</strong></p><p>建议在确认操作前复制或记录密码，以免无法登录 Rescue 系统。</p></blockquote><hr><h2 id="_3、确认强制关机" tabindex="-1">3、确认强制关机 <a class="header-anchor" href="#_3、确认强制关机" aria-label="Permalink to &quot;3、确认强制关机&quot;">​</a></h2><p>进入 Rescue 前，需要勾选：</p><p>☑ <strong>同意执行强制关机</strong></p><blockquote><p><strong>说明：</strong></p><p>Rescue 模式需要重新启动服务器进入独立维护环境，因此系统将执行强制关机。</p><p>请确认当前业务允许中断后再执行操作。</p></blockquote><hr><h2 id="五、启动-rescue-模式" tabindex="-1">五、启动 Rescue 模式 <a class="header-anchor" href="#五、启动-rescue-模式" aria-label="Permalink to &quot;五、启动 Rescue 模式&quot;">​</a></h2><p>确认配置无误后，点击确认启动 Rescue。</p><p>系统将自动执行以下操作：</p><ul><li>强制关闭当前服务器；</li><li>启动至 Rescue 系统；</li><li>创建临时登录环境。</li></ul><p>Rescue 启动完成后，即可使用设置的临时密码登录系统进行维护。</p><hr><h2 id="六、登录-rescue-系统" tabindex="-1">六、登录 Rescue 系统 <a class="header-anchor" href="#六、登录-rescue-系统" aria-label="Permalink to &quot;六、登录 Rescue 系统&quot;">​</a></h2><p>Rescue 系统支持网络连接，可直接远程登录，也可通过 VNC 控制台连接。</p><h2 id="linux-rescue" tabindex="-1">Linux Rescue <a class="header-anchor" href="#linux-rescue" aria-label="Permalink to &quot;Linux Rescue&quot;">​</a></h2><p>支持登录方式：</p><ul><li>SSH</li><li>VNC 控制台</li></ul><p>默认 SSH 登录端口：</p><p><strong>22</strong></p><p>登录用户名请根据 Rescue 系统实际提示使用，密码为创建 Rescue 时设置的临时密码。</p><hr><h2 id="windows-rescue" tabindex="-1">Windows Rescue <a class="header-anchor" href="#windows-rescue" aria-label="Permalink to &quot;Windows Rescue&quot;">​</a></h2><p>支持登录方式：</p><ul><li>远程桌面（RDP）</li><li>VNC 控制台</li></ul><p>默认远程桌面（RDP）端口：</p><p><strong>3389</strong></p><p>登录密码为创建 Rescue 时设置的临时密码。</p><hr><h2 id="七、rescue-模式可以执行哪些操作" tabindex="-1">七、Rescue 模式可以执行哪些操作？ <a class="header-anchor" href="#七、rescue-模式可以执行哪些操作" aria-label="Permalink to &quot;七、Rescue 模式可以执行哪些操作？&quot;">​</a></h2><p>进入 Rescue 系统后，可进行以下维护操作：</p><ul><li>检查系统配置；</li><li>修复系统文件；</li><li>检查磁盘状态；</li><li>挂载系统盘；</li><li>挂载数据盘；</li><li>备份或恢复重要数据；</li><li>修改系统配置文件；</li><li>排查系统启动异常；</li><li>其他系统维护及故障排查操作。</li></ul><blockquote><p><strong>说明：</strong></p><p>如服务器配置了独立数据盘，进入 Rescue 后，<strong>数据盘不会自动挂载，需要手动挂载后方可访问数据。</strong></p></blockquote><hr><h2 id="八、退出-rescue-模式" tabindex="-1">八、退出 Rescue 模式 <a class="header-anchor" href="#八、退出-rescue-模式" aria-label="Permalink to &quot;八、退出 Rescue 模式&quot;">​</a></h2><p>维护完成后，可通过控制台退出 救援系统 模式。</p><blockquote><ol><li>当前 救援系统 按钮将显示为 <strong>退出救援系统</strong>。</li><li>点击 <strong>退出救援系统</strong>。</li></ol><p>系统将自动执行以下操作：</p><ul><li>退出 Rescue 模式；</li><li>自动重启服务器；</li><li>从原操作系统正常启动。</li></ul><blockquote><p><strong>说明：</strong></p><p>点击 <strong>退出救援系统</strong> 后，系统会自动完成服务器重启，无需再次手动重启服务器。</p></blockquote></blockquote><hr><h2 id="九、常见问题" tabindex="-1">九、常见问题 <a class="header-anchor" href="#九、常见问题" aria-label="Permalink to &quot;九、常见问题&quot;">​</a></h2><h3 id="q1-进入-rescue-模式会删除服务器数据吗" tabindex="-1">Q1：进入 Rescue 模式会删除服务器数据吗？ <a class="header-anchor" href="#q1-进入-rescue-模式会删除服务器数据吗" aria-label="Permalink to &quot;Q1：进入 Rescue 模式会删除服务器数据吗？&quot;">​</a></h3><p>不会。</p><p>Rescue 模式不会重装操作系统，也不会格式化服务器磁盘，不会删除服务器中的数据。</p><hr><h3 id="q2-为什么进入-rescue-前需要执行强制关机" tabindex="-1">Q2：为什么进入 Rescue 前需要执行强制关机？ <a class="header-anchor" href="#q2-为什么进入-rescue-前需要执行强制关机" aria-label="Permalink to &quot;Q2：为什么进入 Rescue 前需要执行强制关机？&quot;">​</a></h3><p>Rescue 模式属于独立启动环境。</p><p>服务器需要重新启动进入 Rescue，因此必须执行强制关机操作。</p><hr><h3 id="q3-临时密码可以再次查看吗" tabindex="-1">Q3：临时密码可以再次查看吗？ <a class="header-anchor" href="#q3-临时密码可以再次查看吗" aria-label="Permalink to &quot;Q3：临时密码可以再次查看吗？&quot;">​</a></h3><p>不可以。</p><p>临时密码仅在创建 Rescue 时显示一次。</p><p>请务必提前复制或记录，如遗忘密码，可重新创建 Rescue 并重新设置新的临时密码。</p><hr><h3 id="q4-rescue-系统支持哪些登录方式" tabindex="-1">Q4：Rescue 系统支持哪些登录方式？ <a class="header-anchor" href="#q4-rescue-系统支持哪些登录方式" aria-label="Permalink to &quot;Q4：Rescue 系统支持哪些登录方式？&quot;">​</a></h3><p>支持以下登录方式：</p><p><strong>Linux Rescue</strong></p><ul><li>SSH（默认端口：22）</li><li>VNC 控制台</li></ul><p><strong>Windows Rescue</strong></p><ul><li>远程桌面（RDP，默认端口：3389）</li><li>VNC 控制台</li></ul><p>登录时请使用创建 Rescue 时设置的临时密码。</p><hr><h3 id="q5-为什么进入-rescue-后看不到数据盘" tabindex="-1">Q5：为什么进入 Rescue 后看不到数据盘？ <a class="header-anchor" href="#q5-为什么进入-rescue-后看不到数据盘" aria-label="Permalink to &quot;Q5：为什么进入 Rescue 后看不到数据盘？&quot;">​</a></h3><p>数据盘不会自动挂载。</p><p>请登录 Rescue 系统后，根据操作系统手动完成数据盘挂载，即可正常访问数据。</p><hr><h3 id="q6-维护完成后如何恢复原来的系统" tabindex="-1">Q6：维护完成后如何恢复原来的系统？ <a class="header-anchor" href="#q6-维护完成后如何恢复原来的系统" aria-label="Permalink to &quot;Q6：维护完成后如何恢复原来的系统？&quot;">​</a></h3><p>完成维护后，返回控制台点击 <strong>退出救援系统</strong>。</p><p>系统会自动退出 Rescue 模式，并自动重启服务器，恢复从原操作系统启动。</p><p>无需额外执行重启操作。</p><hr><h3 id="q7-rescue-模式可以联网吗" tabindex="-1">Q7：Rescue 模式可以联网吗？ <a class="header-anchor" href="#q7-rescue-模式可以联网吗" aria-label="Permalink to &quot;Q7：Rescue 模式可以联网吗？&quot;">​</a></h3><p>可以。</p><p>Rescue 系统默认支持网络连接，可直接通过 SSH 或远程桌面（RDP）进行远程维护，也支持使用 VNC 控制台登录。</p><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>⚠️ 进入 Rescue 模式前，请确认业务允许中断，因为系统将执行强制关机。</p><p>⚠️ 临时密码仅显示一次，请及时复制或记录，避免遗忘。</p><p>⚠️ Rescue 模式不会重装操作系统，也不会删除服务器数据。</p><p>⚠️ Rescue 系统支持网络连接，可通过 SSH、远程桌面（RDP）或 VNC 控制台登录。</p><p>⚠️ Linux Rescue 默认 SSH 登录端口为 <strong>22</strong>；Windows Rescue 默认远程桌面（RDP）端口为 <strong>3389</strong>。</p><p>⚠️ 如服务器配置了独立数据盘，进入 Rescue 后需手动挂载数据盘。</p><p>⚠️ 完成维护后，请先退出 Rescue 模式，再重新启动服务器恢复正常运行。</p><hr>',110)])])}const R=a(i,[["render",o]]);export{d as __pageData,R as default};
